// =============================================================================
// tb_lk_multi.v -- self-checking testbench for multi-lane operation
//   LANES frame pairs are fed at once (each lane has its own input stream and its own random gaps);
//   each lane's u/v/flag is compared pixel by pixel with the Python fixed-point model, and total cycles are counted.
//
// Test vectors (generated by Python, concatenated per lane): vectors/frame0.hex etc.; lane l occupies [l*NPIX, (l+1)*NPIX)
// Run-time parameter: +BUBBLE=0 (default 0 = full speed)
// =============================================================================
`timescale 1ns/1ps

module tb_lk_multi;

    `include "params.vh"            // IMG_W, IMG_H, DET_MIN, LANES
    localparam NPIX = IMG_W * IMG_H;

    wire [15:0] cfg_w = IMG_W;      // run-time size
    wire [15:0] cfg_h = IMG_H;
    reg clk = 1'b0;
    always #5 clk = ~clk;
    reg rst = 1'b1;

    reg  [LANES-1:0]    in_valid = {LANES{1'b0}};
    wire [LANES-1:0]    in_ready;
    reg  [8*LANES-1:0]  in_p0 = {8*LANES{1'b0}};
    reg  [8*LANES-1:0]  in_p1 = {8*LANES{1'b0}};
    wire [LANES-1:0]    out_valid, out_flag;
    wire [16*LANES-1:0] out_x, out_y, out_u, out_v;

    lk_multi #(.LANES(LANES), .WMAX(WMAX), .CW(16), .DET_MIN(DET_MIN)) dut (
        .clk(clk), .rst(rst), .cfg_w(cfg_w), .cfg_h(cfg_h),
        .in_valid(in_valid), .in_ready(in_ready), .in_p0(in_p0), .in_p1(in_p1),
        .out_valid(out_valid), .out_x(out_x), .out_y(out_y),
        .out_u(out_u), .out_v(out_v), .out_flag(out_flag)
    );

    reg [7:0]  f0 [0:LANES*NPIX-1];
    reg [7:0]  f1 [0:LANES*NPIX-1];
    reg [15:0] gu [0:LANES*NPIX-1];
    reg [15:0] gv [0:LANES*NPIX-1];
    reg [0:0]  gf [0:LANES*NPIX-1];

    integer bubble_pct;
    integer cycles = 0, first_in = -1, last_out = 0;
    integer nout  [0:LANES-1];
    integer nerr  [0:LANES-1];
    integer nflag [0:LANES-1];

    always @(posedge clk) cycles = cycles + 1;

    initial begin
        $readmemh("vectors/frame0.hex", f0);
        $readmemh("vectors/frame1.hex", f1);
        $readmemh("vectors/golden_u.hex", gu);
        $readmemh("vectors/golden_v.hex", gv);
        $readmemh("vectors/golden_flag.hex", gf);
        if (!$value$plusargs("BUBBLE=%d", bubble_pct)) bubble_pct = 0;
        repeat (3) @(posedge clk);
        rst <= 1'b0;
    end

    genvar l;
    generate
        for (l = 0; l < LANES; l = l + 1) begin : ln
            integer i, seed, idx;

            // ---- input stream of lane l ----
            initial begin
                nout[l] = 0; nerr[l] = 0; nflag[l] = 0;
                seed = 1000 + l * 7919;
                wait (rst == 1'b0);
                i = 0;
                while (i < NPIX) begin
                    in_valid[l]       <= ((($random(seed) % 100) + 100) % 100) >= bubble_pct;
                    in_p0[8*l +: 8]   <= f0[l*NPIX + i];
                    in_p1[8*l +: 8]   <= f1[l*NPIX + i];
                    @(posedge clk);
                    if (in_valid[l] && in_ready[l]) begin
                        if (first_in < 0) first_in = cycles;
                        i = i + 1;
                    end
                end
                in_valid[l] <= 1'b0;
            end

            // ---- output check of lane l ----
            always @(posedge clk) if (out_valid[l]) begin
                idx = out_y[16*l +: 16] * IMG_W + out_x[16*l +: 16];
                if (idx !== nout[l] || out_u[16*l +: 16] !== gu[l*NPIX + idx]
                    || out_v[16*l +: 16] !== gv[l*NPIX + idx] || out_flag[l] !== gf[l*NPIX + idx]) begin
                    nerr[l] = nerr[l] + 1;
                    if (nerr[l] <= 3)
                        $display("LANE %0d MISMATCH at (y=%0d, x=%0d)", l, out_y[16*l +: 16], out_x[16*l +: 16]);
                end
                if (out_flag[l]) nflag[l] = nflag[l] + 1;
                nout[l]  = nout[l] + 1;
                last_out = cycles;
            end
        end
    endgenerate

    // ---- summary after all lanes finish ----
    initial begin : fin
        integer k, alldone, tot_err, tot_out;
        wait (rst == 1'b0);
        alldone = 0;
        while (!alldone) begin
            @(posedge clk);
            alldone = 1;
            for (k = 0; k < LANES; k = k + 1)
                if (nout[k] < NPIX) alldone = 0;
        end
        repeat (2) @(posedge clk);
        tot_err = 0; tot_out = 0;
        $display("------------------------------------------------------------");
        for (k = 0; k < LANES; k = k + 1) begin
            $display("LANE %0d outputs %0d errors %0d flag %0d", k, nout[k], nerr[k], nflag[k]);
            tot_err = tot_err + nerr[k];
            tot_out = tot_out + nout[k];
        end
        $display("Image %0dx%0d, LANES=%0d, bubble=%0d%%", IMG_W, IMG_H, LANES, bubble_pct);
        $display("Cycles first pixel in -> last output of all lanes: %0d", last_out - first_in + 1);
        if (tot_err == 0 && tot_out == LANES * NPIX)
            $display("*** PASS ***");
        else
            $display("*** FAIL ***");
        $display("------------------------------------------------------------");
        $finish;
    end

    initial begin
        #(64'd10 * NPIX * 40 * 20);
        $display("*** FAIL: TIMEOUT ***");
        $finish;
    end

endmodule
